function renderResults(){if(!loaded)return;syncCatalogControls();const signature=JSON.stringify([query,category,subtype,typeFilter,setFilter,markOnly,current()?.format,uniqueOnly,order]);if(signature!==searchSignature){$('.results-scroll').scrollTop=0;searchSignature=signature;}const arr=filtered(),pages=Math.max(1,Math.ceil(arr.length/36));page=Math.min(page,pages);const slice=arr.slice((page-1)*36,page*36);const counts=new Map(current().cards.map(e=>[e.id,e.qty]));$('#resultCount').innerHTML=`<b>${arr.length.toLocaleString()}</b> ${L('개의 카드','cards')}`;$('#results').innerHTML=slice.length?slice.map(c=>`<article class="result-card" draggable="true" data-card-id="${c.id}" data-origin="library"><div class="card-image-wrap" role="button" tabindex="0" data-action="detail" data-id="${c.id}" aria-label="${esc(c.name)} ${L('상세 보기','details')}">${imageMarkup(c)}${counts.has(c.id)?`<span class="in-deck">×${counts.get(c.id)}</span>`:''}<button class="result-add" data-action="add" data-id="${c.id}" aria-label="${esc(c.name)} ${L('덱에 추가','add to deck')}" title="${L('덱에 1장 추가','Add one to deck')}">${icon('plus')}</button></div><span class="result-name">${esc(c.name)}</span><div class="result-meta"><span>${esc(c.set)} · ${esc(c.number)}</span><span>${esc(c.mark)}</span></div></article>`).join(''):`<div class="no-results">${icon('search')}${L('검색 결과가 없어요.','No cards found.')}<br>${L('다른 이름이나 필터를 사용해 보세요.','Try a different name or filter.')}<p><button class="btn sm" data-action="reset-filters">${L('필터 초기화','Reset filters')}</button></p></div>`;
 $('#pagination').innerHTML=`<button class="icon-btn" data-action="prev" ${page<=1?'disabled':''} aria-label="${L('이전 페이지','Previous page')}">${icon('left')}</button><span>${page} / ${pages}</span><button class="icon-btn" data-action="next" ${page>=pages?'disabled':''} aria-label="${L('다음 페이지','Next page')}">${icon('right')}</button>`;
}
