 $('#deckStats').innerHTML=`<div class="stats-strip">${GROUPS.map(g=>`<div class="stat"><div class="stat-symbol ${g}">${icon(GROUP_ICONS[g])}</div><div class="stat-text"><span>${lab[g]}</span><b>${s[g]}</b></div></div>`).join('')}</div><div class="distribution">${GROUPS.map(g=>`<span style="width:${s.total?s[g]/s.total*100:33.33}%;opacity:${s.total?1:.28}"></span>`).join('')}</div>`;
 $('#canvas').innerHTML=(!d.cards.length?`<div class="empty-canvas"><div class="starter-scene" aria-hidden="true"><div class="starter-orbit"></div><div class="starter-card starter-card-a">${ballMark()}</div><div class="starter-card starter-card-b">${ballMark()}</div><img class="starter-pikachu" src="./art/pikachu.png" width="475" height="475" alt="" draggable="false"><span class="starter-spark spark-one">${icon('spark')}</span><span class="starter-spark spark-two">${icon('spark')}</span></div><div class="starter-kicker">YOUR ADVENTURE STARTS HERE</div><h3>${L('너로 정했다, 나만의 덱!','I choose you, my next deck!')}</h3><p>${L('마음에 드는 카드를 끌어와 나만의 팀을 만들어보세요.<br>포켓몬, 트레이너스, 에너지는 자동으로 정리돼요.','Drag your favorite cards here and build your team.<br>Pokémon, Trainers and Energy sort themselves.')}</p><button class="btn" data-action="example">${icon('pokeball')}${L('예시 덱으로 시작하기','Start with an example deck')}${icon('arrow')}</button></div>`:'')+`<div class="sections ${!d.cards.length?'empty-sections':''}">${GROUPS.map(g=>{const es=d.cards.filter(e=>byId.get(e.id)?.group===g);return `<section class="deck-section" style="--group-color:${COLORS[g]}"><div class="section-heading"><span class="section-type-icon">${icon(GROUP_ICONS[g])}</span>${lab[g]}<span class="section-count">${s[g]}</span><span class="line"></span></div>${d.cards.length?`<div class="deck-cards ${view==='list'?'list':''}">${es.length?es.map(e=>deckCard(e)).join(''):`<div class="section-empty">${L('아직 카드가 없어요','No cards yet')}</div>`}</div>`:''}</section>`;}).join('')}</div>`;
 $('#saveStatus').innerHTML=`${icon(storageFailed?'info':'checkcircle')}${storageFailed?L('저장 실패 · 내보내기 필요','Not saved · export a backup'):L('이 브라우저에 자동 저장','Autosaved in this browser')}`;
 $('#undo').disabled=!history.length;$('#redo').disabled=!future.length;$('#mobileCount').textContent=`${s.total}/${d.target}`;
 $$('.segmented button').forEach(b=>b.classList.toggle('active',b.dataset.action==='view-'+view));renderValidation();
