function add(id){if(!byId.has(id))return;if(stats(current(),byId).total>=999)return toast(L('최대 999장까지 편집할 수 있어요.','The editing limit is 999 cards.'),true);stash();const e=current().cards.find(e=>e.id===id);if(e)e.qty++;else current().cards.push({id,qty:1});update();const c=byId.get(id);toast(`${c.name} ${L('추가됨','added')}`);const count=$('#detailCount');if(count)count.textContent=L(`덱에 ${e?e.qty:1}장`,`${e?e.qty:1} in deck`);}
function remove(id){const e=current().cards.find(e=>e.id===id);if(!e)return;stash();e.qty--;current().cards=current().cards.filter(e=>e.qty>0);update();}
function setCurrent(id){if(!decks.some(d=>d.id===id))return;activeId=id;history=[];future=[];persist();renderDeck();renderResults();}
function undo(redo=false){const source=redo?future:history,dest=redo?history:future;if(!source.length)return;dest.push(snapshot());const d=JSON.parse(source.pop());decks[decks.findIndex(x=>x.id===activeId)]=d;update();}
