function exportValue(){return exportMode==='json'?JSON.stringify({app:'PTCG Canvas',version:2,name:current().name,target:current().target,format:current().format,recipe:current().recipe,cards:current().cards},null,2):exportText(current(),byId);}
function showExport(){const modes=[['recipe',L('공식 레시피','Official deck sheet')],['text',L('텍스트 목록','Text list')],['json','JSON '+L('백업','backup')]],tabs=`<div class="export-tabs">${modes.map(([m,label])=>`<button class="chip ${exportMode===m?'active':''}" data-action="export-${m}">${label}</button>`).join('')}</div>`;
 if(exportMode==='recipe'){const d=current(),v=validateDeck(d,byId,legalityIndex);let recipe,error='';try{recipe=buildRecipe(d,byId);}catch(e){error=e.message;}
 modal(L('공식 레시피 내보내기','Export official deck sheet'),`${tabs}<p>${L('첨부한 2026 덱 기입용지에 카드명·시리즈 마크·컬렉션 넘버·장수와 합계를 채웁니다.','Fills the supplied 2026 form with card names, series marks, collection numbers, quantities and totals.')}</p><div class="recipe-profile"><label>${L('플레이어 이름','Player name')}<input id="recipeName" maxlength="50" value="${esc(d.recipe?.name||'')}" placeholder="${L('미입력 시 빈칸으로 출력','Leave blank to fill by hand')}"></label><label>${L('참가 부문 · 2026 양식','Division · 2026 form')}<select id="recipeDivision"><option value="">${L('선택하지 않음','Leave blank')}</option>${Object.entries(DIVISIONS).map(([k,val])=>`<option value="${k}" ${d.recipe?.division===k?'selected':''}>${val}</option>`).join('')}</select></label></div><div class="recipe-status ${v.ok?'good':'review'}">${icon(v.ok?'checkcircle':'info')}<span>${formatLabel(d.format)} · ${legalityText(v)}${v.ok?'':' · '+L('미완성 덱도 초안으로 내보낼 수 있어요.','Draft export is allowed.')}</span></div>${error?`<p class="recipe-error">${esc(error)}</p>`:`<div class="recipe-preview" id="recipePreview">${recipeHTML(recipe,d.recipe)}</div>`}<p class="tiny">${L('A4 가로 · XLSX는 원본 양식 유지 · 인쇄/PDF는 같은 3열 배치. 부문 연령은 첨부한 2026 양식 기준입니다.','A4 landscape · XLSX preserves the original template; Print/PDF uses the same three-column layout. Division ages follow the supplied 2026 form.')}</p><div class="dialog-actions"><button class="btn" data-action="recipe-print" ${error||!d.cards.length?'disabled':''}>${icon('print')}${L('공식 양식 인쇄 / PDF','Print sheet / PDF')}</button><button class="btn primary" data-action="recipe-xlsx" ${error||!d.cards.length?'disabled':''}>${icon('export')}${L('엑셀(.xlsx) 저장','Download .xlsx')}</button></div>`,'TOURNAMENT DECK SHEET');$('#dialog').classList.add('recipe-dialog');return;}
 modal(L('덱 내보내기','Export deck'),`${tabs}<p>${L('텍스트 목록으로 공유하거나 JSON으로 정확한 카드 판본과 덱 형식을 백업하세요.','Share a text list, or back up exact printings and the deck format as JSON.')}</p><textarea id="exportText" spellcheck="false" readonly aria-label="${L('내보낼 덱 내용','Exported deck data')}">${esc(exportValue())}</textarea><div class="dialog-actions"><button class="btn" data-action="print">${icon('print')}${L('카드 이미지 인쇄','Print card images')}</button><button class="btn" data-action="copy-export">${icon('copy')}${L('복사','Copy')}</button><button class="btn primary" data-action="download">${icon('export')}${L('파일 저장','Download')}</button></div>`,'EXPORT');}
function saveRecipeProfile(){current().recipe={name:$('#recipeName')?.value||'',division:$('#recipeDivision')?.value||''};persist();if($('#recipePreview'))$('#recipePreview').innerHTML=recipeHTML(buildRecipe(current(),byId),current().recipe);}
async function exportRecipe(print=false){saveRecipeProfile();const recipe=buildRecipe(current(),byId);if(print){$('#printArea').innerHTML=recipeHTML(recipe,current().recipe);document.body.classList.add('printing-recipe');$('#dialog').close();window.print();return;}const button=$('[data-action="recipe-xlsx"]');button.disabled=true;try{const response=await fetch('./templates/recipe-template-2026.json');if(!response.ok)throw Error(L('엑셀 양식을 불러올 수 없습니다.','Could not load the Excel template.'));const bytes=createRecipeXlsx(await response.json(),recipe,current().recipe);saveBlob(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),current().name+'_공식레시피_2026.xlsx');toast(L('공식 레시피 XLSX를 저장했어요.','Official deck sheet downloaded.'));}catch(e){toast(e.message,true);}finally{button.disabled=false;}}
function saveBlob(blob,filename){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=filename.replace(/[\\/:*?"<>|]/g,'_');a.click();setTimeout(()=>URL.revokeObjectURL(u),3000);}
window.addEventListener('afterprint',()=>document.body.classList.remove('printing-recipe'));

function download(){const b=new Blob([exportValue()],{type:exportMode==='json'?'application/json':'text/plain;charset=utf-8'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=current().name.replace(/[\\/:*?"<>|]/g,'_')+(exportMode==='json'?'.json':'.txt');a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);}
async function printDeck(){document.body.classList.remove('printing-recipe');if(!current().cards.length)return toast(L('먼저 카드를 추가해 주세요.','Add cards first.'),true);const lab=labels(),d=current();$('#printArea').innerHTML=`<h1>${esc(d.name)}</h1><div class="print-meta">PTCG Canvas · ${stats(d,byId).total}/${d.target} ${L('장','cards')} · ${new Date().toLocaleDateString()}</div>${GROUPS.map(g=>{const es=d.cards.filter(e=>byId.get(e.id).group===g);return es.length?`<h2>${lab[g]} · ${es.reduce((n,e)=>n+e.qty,0)}</h2><div class="print-grid">${es.map(e=>{const c=byId.get(e.id);return`<div class="print-card"><img src="${esc(c.localImage||c.image)}" data-cid="${c.id}" data-try="${c.localImage?'0':'1'}" alt="${esc(c.name)}"><p><b>${e.qty} × ${esc(c.name)}</b><br>${esc(c.set)} ${esc(c.number)}</p></div>`;}).join('')}</div>`:'';}).join('')}<div class="print-footer">${L('개인 덱 기록용 · 공식 대회 제출 양식이 아닙니다.','Personal deck record · not an official tournament submission form.')}<br>© Pokémon / Nintendo / Creatures / GAME FREAK</div>`;toast(L('인쇄할 카드 이미지를 준비하고 있어요…','Preparing card images for printing…'));const imgs=$$('#printArea img');await Promise.all(imgs.map(im=>im.complete?Promise.resolve():new Promise(r=>{im.onload=r;im.addEventListener('error',r,{once:true});setTimeout(r,12000);})));$('#dialog').close();window.print();}
const tutorial=createTutorial({
 getLanguage:()=>lang,
 hasCards:()=>!!current().cards.length,
 capture:()=>({mobile,exportMode,parsed,filtersExpanded,checksOpen:$('#validation details')?.open,scrolls:$$('.library,.results-scroll,.workspace').map(el=>({el,top:el.scrollTop,left:el.scrollLeft}))}),
 prepare:step=>{
  $('#dialog').close();$('#dialog').classList.remove('tutorial-preview');
  mobile=step.area;$('.layout').className='layout mobile-'+mobile;$$('.mobile-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.action==='mobile-'+mobile));
  filtersExpanded=['chips','types','sets'].includes(step.id);renderFilters();
  if(step.reveal==='detail')detail($('#results [data-card-id]')?.dataset.cardId||current().cards[0]?.id||cards[0].id);
  if(step.reveal==='validation')$('#validation details').open=true;
  if(step.reveal==='decks')showDecks();
  if(step.reveal==='import')showImport();
  if(step.reveal==='recipe'||step.reveal==='backup'){exportMode=step.reveal==='backup'?'json':'recipe';showExport();}
  if($('#dialog').open)$('#dialog').classList.add('tutorial-preview');
 },
 restore:state=>{
  $('#dialog').close();$('#dialog').classList.remove('tutorial-preview');mobile=state.mobile;exportMode=state.exportMode;parsed=state.parsed;filtersExpanded=state.filtersExpanded;renderFilters();
  $('.layout').className='layout mobile-'+mobile;$$('.mobile-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.action==='mobile-'+mobile));
  if($('#validation details'))$('#validation details').open=state.checksOpen;
  state.scrolls.forEach(({el,top,left})=>{el.scrollTop=top;el.scrollLeft=left;});
 }
});
async function example(){const data=await fetch('./data/example.json').then(r=>r.json());const d={...newDeck(),name:L(data.name,'Dragapult × Lucario · editing example'),cards:mergeEntries(data.cards,byId),target:data.target};decks.push(d);setCurrent(d.id);mobile='deck';renderShell();toast(L('편집용 예시 덱을 새로 열었어요. 대회 추천 덱은 아닙니다.','Opened an editing example, not a tournament deck recommendation.'));}
function confirmAction(title,body,action,id=''){modal(title,`<p>${esc(body)}</p><div class="dialog-actions"><button class="btn" data-action="close">${L('취소','Cancel')}</button><button class="btn danger" data-action="${action}" data-id="${esc(id)}">${L('확인','Confirm')}</button></div>`);}
async function action(e){const b=e.target.closest('[data-action]');if(!b||b.disabled||!loaded)return;const a=b.dataset.action,id=b.dataset.id;e.stopPropagation();
 switch(a){case 'theme':{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';try{localStorage.setItem('ptcg.theme',dark?'dark':'light');}catch{}b.setAttribute('aria-pressed',String(dark));b.innerHTML=icon(dark?'spark':'darkness')+'<span>'+L(dark?'라이트':'블랙',dark?'Light':'Dark')+'</span>';break;}case 'recipe':case 'export-recipe':exportMode='recipe';showExport();break;case 'recipe-xlsx':await exportRecipe();break;case 'recipe-print':await exportRecipe(true);break;case 'add':add(id);break;case 'remove':remove(id);break;case 'detail':detail(id);break;case 'close':$('#dialog').close();break;case 'language':lang=lang==='ko'?'en':'ko';try{localStorage.setItem('ptcg.lang',lang);}catch{}$('#dialog').close();renderShell();break;
 case 'toggle-filters':filtersExpanded=!filtersExpanded;catalogPreferences.expanded=filtersExpanded;saveCatalog();$('#advancedFilters').hidden=!filtersExpanded;syncCatalogControls();break;
 case 'category':category=b.dataset.value;subtype='';page=1;renderFilters();renderResults();break;case 'type':typeFilter=typeFilter===b.dataset.value?'':b.dataset.value;page=1;renderFilters();renderResults();break;case 'subtype':subtype=subtype===b.dataset.value?'':b.dataset.value;page=1;renderFilters();renderResults();break;
 case 'reset-filters':query='';category='all';subtype='';typeFilter='';setFilter='';uniqueOnly=false;order='featured';page=1;$('#search').value='';renderFilters();renderResults();break;
 case 'prev':page--;renderResults();$('.results-scroll').scrollTop=0;break;case 'next':page++;renderResults();$('.results-scroll').scrollTop=0;break;
 case 'view-grid':case 'view-list':view=a.slice(5);renderDeck();break;case 'undo':undo();break;case 'redo':undo(true);break;
 case 'sort':stash();current().cards.sort((a,b)=>GROUPS.indexOf(byId.get(a.id).group)-GROUPS.indexOf(byId.get(b.id).group)||byId.get(a.id).name.localeCompare(byId.get(b.id).name,'ko'));update();toast(L('이름 순으로 정렬했어요.','Sorted cards by name.'));break;
 case 'clear':if(!current().cards.length)return;confirmAction(L('덱을 비울까요?','Clear this deck?'),L('카드가 모두 제거됩니다. 실행 취소로 되돌릴 수 있어요.','All cards will be removed. You can undo this action.'),'clear-confirm');break;case 'clear-confirm':stash();current().cards=[];update();$('#dialog').close();break;
 case 'new':{const d=newDeck();decks.push(d);setCurrent(d.id);$('#dialog').close();mobile='deck';renderShell();$('#deckName').focus();$('#deckName').select();break;}
 case 'decks':showDecks();break;case 'open-deck':setCurrent(id);$('#dialog').close();mobile='deck';renderShell();break;
 case 'duplicate':{const src=decks.find(x=>x.id===id);const d={...JSON.parse(JSON.stringify(src)),id:uid(),name:src.name+L(' · 사본',' · copy'),updated:Date.now()};decks.push(d);setCurrent(d.id);showDecks();break;}
 case 'delete-deck':confirmAction(L('저장된 덱을 삭제할까요?','Delete this saved deck?'),L('이 덱은 삭제 후 복구할 수 없습니다. 필요하면 먼저 JSON으로 내보내 주세요.','This cannot be undone. Export JSON first if you need a backup.'),'delete-confirm',id);break;
 case 'delete-confirm':decks=decks.filter(d=>d.id!==id);if(!decks.length)decks=[newDeck()];if(activeId===id)activeId=decks[0].id;history=[];future=[];update();showDecks();break;
 case 'example':try{await example();}catch(err){toast(L('예시 덱을 불러오지 못했어요.','Could not load example deck.'),true);}break;case 'tutorial':tutorial.start();break;case 'import':showImport();break;case 'preview-import':previewImport();break;
 case 'apply-import':if(parsed&&!parsed.errors.length&&parsed.entries.length){const d={...newDeck(),name:parsed.name||L('가져온 덱','Imported deck'),target:parsed.target,format:parsed.format,recipe:parsed.recipe,cards:parsed.entries};decks.push(d);setCurrent(d.id);$('#dialog').close();mobile='deck';renderShell();toast(L('새 덱으로 가져왔어요.','Imported as a new deck.'));}break;
 case 'export':showExport();break;case 'export-text':exportMode='text';showExport();break;case 'export-json':exportMode='json';showExport();break;case 'copy-export':try{await navigator.clipboard.writeText(exportValue());toast(L('덱 목록을 복사했어요.','Deck copied.'));}catch{$('#exportText').select();toast(L('텍스트를 선택했어요. Ctrl/Cmd+C로 복사하세요.','Text selected. Press Ctrl/Cmd+C to copy.'));}break;case 'download':download();break;case 'print':await printDeck();break;
 case 'mobile-library':case 'mobile-deck':mobile=a.slice(7);$('.layout').className='layout mobile-'+mobile;$$('.mobile-tabs button').forEach(x=>x.classList.toggle('active',x.dataset.action===a));break;
 case 'focus-search':mobile='library';$('.layout').className='layout mobile-library';$('#search').focus();break;
 }
}
document.addEventListener('click',e=>{action(e).catch(err=>{console.error(err);toast(L('작업을 완료하지 못했어요. 다시 시도해 주세요.','The action failed. Please try again.'),true);});});
document.addEventListener('input',e=>{if(e.target.id==='recipeName')saveRecipeProfile();if(e.target.id==='deckName'){if(!e.target.dataset.editing){stash();e.target.dataset.editing='true';}current().name=e.target.value;persist();}if(e.target.id==='search'){query=e.target.value;page=1;clearTimeout(searchTimer);searchTimer=setTimeout(renderResults,120);}if(e.target.id==='importText'){parsed=null;if($('#applyImport'))$('#applyImport').disabled=true;}});
document.addEventListener('change',async e=>{const t=e.target;switch(t.id){case 'recipeDivision':saveRecipeProfile();break;case 'deckFormat':stash();current().format=t.value;page=1;update();break;case 'setFilter':setFilter=t.value;page=1;renderResults();break;case 'markOnly':markOnly=t.checked;catalogPreferences.formatOnly=markOnly;saveCatalog();page=1;renderResults();break;case 'uniqueOnly':uniqueOnly=t.checked;page=1;renderResults();break;case 'sortOrder':order=t.value;page=1;renderResults();break;case 'deckName':if(!t.dataset.editing)stash();current().name=t.value.trim()||L('이름 없는 덱','Untitled deck');t.value=current().name;delete t.dataset.editing;persist();break;case 'target':stash();current().target=Number(t.value);update();break;case 'importFile':{const f=t.files[0];if(!f)return;if(f.size>2e6){toast(L('덱 파일은 2MB 이하로 선택해 주세요.','Deck files must be under 2 MB.'),true);return;}$('#importText').value=await f.text();previewImport();break;}}});
document.addEventListener('keydown',e=>{if(!loaded)return;if(e.target.matches('[role=button]')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.click();return;}const typing=/INPUT|TEXTAREA|SELECT/.test(e.target.tagName);if(!typing&&!$('#dialog').open&&e.key==='/'){e.preventDefault();$('#search').focus();return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!typing&&!$('#dialog').open){e.preventDefault();undo(e.shiftKey);}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();if(loaded){persist();toast(L('현재 덱을 저장했어요.','Deck saved.'));}}});
document.addEventListener('dragstart',e=>{const node=e.target.closest('[draggable=true][data-card-id]');if(!node)return;dragging={id:node.dataset.cardId,origin:node.dataset.origin};e.dataTransfer.setData('application/x-ptcg-card',JSON.stringify(dragging));e.dataTransfer.setData('text/plain',dragging.id);e.dataTransfer.effectAllowed=dragging.origin==='deck'?'move':'copy';});
document.addEventListener('dragover',e=>{const zone=e.target.closest('#canvas,#trash');if(!zone||(!dragging&&!e.dataTransfer.types.includes('application/x-ptcg-card')))return;e.preventDefault();zone.classList.add('dragover');e.dataTransfer.dropEffect=zone.id==='trash'?'move':dragging?.origin==='deck'?'move':'copy';});
document.addEventListener('dragleave',e=>{const zone=e.target.closest('#canvas,#trash');if(zone&&!zone.contains(e.relatedTarget))zone.classList.remove('dragover');});
document.addEventListener('drop',e=>{const zone=e.target.closest('#canvas,#trash');if(!zone)return;e.preventDefault();$$('.dragover').forEach(x=>x.classList.remove('dragover'));let data;try{data=JSON.parse(e.dataTransfer.getData('application/x-ptcg-card'));}catch{data=dragging;}if(!data||!byId.has(data.id))return;if(zone.id==='trash'){if(data.origin==='deck')remove(data.id);}else if(data.origin!=='deck')add(data.id);dragging=null;});
document.addEventListener('dragend',()=>{dragging=null;$$('.dragover').forEach(x=>x.classList.remove('dragover'));});
document.addEventListener('error',e=>{const im=e.target;if(im.tagName!=='IMG'||!im.dataset.cid)return;const c=byId.get(im.dataset.cid);if(!c)return;const stage=Number(im.dataset.try||0);if(stage===0){im.dataset.try='1';im.src=c.image;}else if(stage===1&&c.originalImage){im.dataset.try='2';im.src=c.originalImage;}else{im.style.visibility='hidden';im.alt=L('이미지를 불러오지 못했습니다: ','Image unavailable: ')+c.name;}},true);
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#dialog').close();}});
async function loadData(){let data;if('DecompressionStream' in window){try{const r=await fetch('./data/cards.json.gz');if(!r.ok)throw Error();data=await new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).json();}catch{data=null;}}if(!data){const r=await fetch('./data/cards.json');if(!r.ok)throw Error('Card database unavailable');data=await r.json();}return data;}
try{[cards,meta]=await Promise.all([loadData(),fetch('./data/meta.json').then(r=>{if(!r.ok)throw Error();return r.json();})]);for(const c of cards){c.search=normalizeName([c.name,c.set,c.number,c.setName,c.text,c.types.join(' '),c.attacks.map(a=>a.name+' '+a.effect).join(' '),c.tags.join(' ')].join(' '));byId.set(c.id,c);}legalityIndex=createLegalityIndex(cards);initStorage();loaded=true;renderShell();}catch(err){console.error(err);$('#app').innerHTML=`<div class="boot"><div class="brand-symbol">PC</div><strong>PTCG Canvas</strong><p>${L('카드 데이터베이스를 불러오지 못했어요. 연결을 확인하고 다시 열어 주세요.','The card database could not be loaded. Check your connection and reload.')}</p><button class="btn primary" id="retryLoad">${L('다시 시도','Retry')}</button></div>`;$('#retryLoad').onclick=()=>location.reload();}

